-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.query_to_tsquery(query text)
 RETURNS tsquery
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select to_tsquery(
    'public.es'::regconfig,
    coalesce(
      (select string_agg(quote_literal(p) || ':*', ' & ')
         from regexp_split_to_table(
                regexp_replace(left(coalesce(query, ''), 200), '[^[:alnum:][:space:]-]', ' ', 'g'),
                '\s+') as p
        where p <> '' and p !~ '^-+$'),
      '')
  );
$function$;

grant execute on function public.query_to_tsquery(query text) to service_role;
